/* 
IF(ISPICKVAL( TSGCFG__Consolidation_Method__c , 'Average') && TSGCFG__PrinterTotalCPCColorLineItem__c > 0 ,
TSGCFG__PrinterSumofCPCColor5__c / TSGCFG__PrinterTotalCPCColorLineItem__c,
IF( ABS(TSGCFG__PrinterTotalColor5Volume__c - TSGCFG__PrinterTotalVolumeIncludesColor5__c)<> 0, TSGCFG__PrinterTotalColor5MonthlyCost__c / ABS(TSGCFG__PrinterTotalColor5Volume__c - TSGCFG__PrinterTotalVolumeIncludesColor5__c),
IF( TSGCFG__PrinterTotalCPCColorLineItem__c > 0, TSGCFG__PrinterSumofCPCColor5__c / TSGCFG__PrinterTotalCPCColorLineItem__c, 0
)
)
)
*/

IF(ISPICKVAL( TSGCFG__CPC_Consolidation__r.TSGCFG__Consolidation_Method__c , 'Average') && TSGCFG__CPC_Consolidation__r.TSGCFG__PrinterTotalCPCColorLineItem__c > 0 ,
TSGCFG__CPC_Consolidation__r.TSGCFG__PrinterSumofCPCColor5__c / TSGCFG__CPC_Consolidation__r.TSGCFG__PrinterTotalCPCColorLineItem__c,
IF( ABS(TSGCFG__CPC_Consolidation__r.TSGCFG__PrinterTotalColor5Volume__c - TSGCFG__CPC_Consolidation__r.TSGCFG__PrinterTotalVolumeIncludesColor5__c)<> 0, TSGCFG__CPC_Consolidation__r.TSGCFG__PrinterTotalColor5MonthlyCost__c / ABS(TSGCFG__CPC_Consolidation__r.TSGCFG__PrinterTotalColor5Volume__c - TSGCFG__CPC_Consolidation__r.TSGCFG__PrinterTotalVolumeIncludesColor5__c),
IF( TSGCFG__CPC_Consolidation__r.TSGCFG__PrinterTotalCPCColorLineItem__c > 0, TSGCFG__CPC_Consolidation__r.TSGCFG__PrinterSumofCPCColor5__c / TSGCFG__CPC_Consolidation__r.TSGCFG__PrinterTotalCPCColorLineItem__c, 0
)
)
)
